/**
 * Confluence Node - Version 1
 * Discriminator: resource=page, operation=get
 */


interface Credentials {
  confluenceCloudOAuth2Api: CredentialReference;
  atlassianServiceAccountApi: CredentialReference;
}

/** Retrieve a page, optionally with its full sub-tree */
export type ConfluenceV1PageGetParams = {
  resource: 'page';
  operation: 'get';
  authentication?: 'cloudOAuth2' | 'serviceAccount';
/**
 * The Confluence site to use. Can be left empty when the connection has access to exactly one site.
 * @searchListMethod getSites
 * @default {"mode":"list","value":""}
 */
    site?: { __rl: true; mode: 'list' | 'url'; value: string; cachedResultName?: string };
/**
 * Limits page selection and By Title lookups to one space. Leave empty or pick "All Spaces" to search across all spaces.
 * @searchListMethod searchSpacesWithAll
 * @default {"mode":"list","value":""}
 */
    space?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * The page to fetch
 * @searchListMethod getPages
 * @default {"mode":"list","value":""}
 */
    page?: { __rl: true; mode: 'list' | 'url' | 'id' | 'title'; value: string; cachedResultName?: string };
/**
 * Body Format
 * @default storage
 */
    bodyFormat?: 'atlas_doc_format' | 'plainText' | 'storage' | Expression<string>;
/**
 * Whether to also fetch every descendant page of the page, one item per page. Unpublished drafts are skipped.
 * @default false
 */
    includeDescendants?: boolean | Expression<boolean>;
/**
 * Safeguard that stops the sub-tree walk after this many pages, root included
 * @displayOptions.show { includeDescendants: [true] }
 * @default 100
 */
    maxPages?: number | Expression<number>;
};

export type ConfluenceV1PageGetNode = {
  type: 'n8n-nodes-base.confluence';
  version: 1;
  config: NodeConfig<ConfluenceV1PageGetParams> & { credentials?: Credentials };
};